    transfer: [
      B.text('c1_010_t_situation', 'Kontroll: kirjutamine ja rääkimine (Harno C1)', 'Selle lehe osad on nagu Harno C1 eksamil. Kirjutamine 2: arvamuslugu 220–260 sõna (umbes 45 minutit). Rääkimine paaris: 2-minutiline kõne pärast 3-minutilist ettevalmistust, partneri küsimused ja umbes 7-minutiline arutelu. Kirjutamise osa 1 (andmete kokkuvõtte) tegid Avasta lehel. Olukord: linn kavatseb kõik teated ja otsused kirjutada edaspidi lihtsas keeles. Kohalik ajaleht kogub lugejate arvamusi.'),
      B.errorfix('c1_010_t_fix', 'Enne kirjutamist: tüüpvead.', 'Igas lauses on üks sihitise või rektsiooni viga. Paranda.', [['Palun saatke aruande hiljemalt homseks kella kümneks, et jõuaksime selle enne koosolekut läbi vaadata.', 'Palun saatke aruanne hiljemalt homseks kella kümneks, et jõuaksime selle enne koosolekut läbi vaadata.'], ['Projekti edu sõltub suuresti meeskonna, sest ükski juht ei suuda kõike üksinda ära teha.', 'Projekti edu sõltub suuresti meeskonnast, sest ükski juht ei suuda kõike üksinda ära teha.'], ['Ma nõustun artikli autorit selles, et liigne viisakus võib rahvusvahelises meeskonnas palju energiat kulutada.', 'Ma nõustun artikli autoriga selles, et liigne viisakus võib rahvusvahelises meeskonnas palju energiat kulutada.'], ['Mul on juba ammu olnud suur huvi kultuuridevahelisest suhtlusest ja selle uurimisest.', 'Mul on juba ammu olnud suur huvi kultuuridevahelise suhtluse ja selle uurimise vastu.'], ['Ma ootan tema vastus juba teist nädalat, kuigi ta lubas mulle kirjutada kohe pärast puhkust.', 'Ma ootan tema vastust juba teist nädalat, kuigi ta lubas mulle kirjutada kohe pärast puhkust.'], ['Pärast pikka kaalumist loobus ta oma plaani kolida pealinna ja jäi kodulinna tööle.', 'Pärast pikka kaalumist loobus ta oma plaanist kolida pealinna ja jäi kodulinna tööle.']]),
      B.planning('c1_010_t_prep', 'Plaan.', 'Kirjuta märksõnad: arvamusloo jaoks 5 minutit, kõne jaoks 3 minutit.', ['Arvamuslugu: seisukoht ja pealkiri.', 'Punkt 1: kellele lihtne keel kasu toob ja kellele võib see tunduda lugupidamatu? Näide.', 'Punkt 2: kas ametlik täpsus kannatab? Näide.', 'Kõne: valitud teema, kolm märksõna ja kokkuvõtte lause.']),
      B.letter('c1_010_t_w2', 'Kirjutamine 2: arvamuslugu (220–260 sõna).', 'Kirjuta ajalehele arvamuslugu „Kas linn peaks kirjutama lihtsas keeles?”. Arenda mõlemat punkti, too näiteid ja tee järeldus. Pöördu avalikkuse poole, ära mine isiklikuks.', 'Pealkiri:', 'Autor:', [220, 260]),
      B.speaking('c1_010_t_say', 'Rääkimine 1: kõne (2 minutit).', 'Vali kaardilt üks teema. Valmistu 3 minutit ja räägi 2 minutit: pöördumine, arendus, lühike kokkuvõte. Partner esitab seejärel 1–2 küsimust.', ['Teema A: Kuidas anda tagasisidet rahvusvahelises meeskonnas?', 'Teema B: Millises registris peaks ettevõte suhtlema klientidega sotsiaalmeedias?', 'Partneri küsimus: Kas sinu ettepanek sobiks ka väikesele ettevõttele?', 'Partneri küsimus: Mis võiks sinu lahenduse puhul valesti minna?'], [100, 140], ['Lubage mul alustada…', 'Esiteks…, teiseks…', 'Kokkuvõtteks…']),
      B.rolecards('c1_010_t_disc', 'Rääkimine 2: arutelu (umbes 7 minutit).', 'Arutlege teemakaardi põhjal. Võtke ja andke sõna, põhjendage näidetega. Ärge pidage monoloogi.',
        'Teemakaart: „Kas otsekohesus on töökohal viisakusest väärtuslikum?” Mõtted: viisakuse maks; toorus ei ole ausus; suhtlusleping; kultuurierinevused. Alusta oma seisukohaga ja küsi partneri arvamust.', 'Sama teemakaart. Ole osaliselt eri meelt, too näide oma kogemusest, võta viisakalt sõna ja anna see tagasi. Lõpus võtke koos kokku, milles olete ühel meelel.',
        ['Minu meelest…, aga mida sina arvad?', 'Kui tohin vahele öelda…', 'Tulles tagasi sinu näite juurde…'], ['Ma näen seda veidi teisiti…', 'Lubage mul mõte lõpetada…', 'Kas oleme siis ühel meelel, et…?']),
      B.rubric('c1_010_t_score', 'Hindamine (Harno C1).', 'Õpetaja või paariline märgib punktid.', ['Kirjutamine 1 (Avasta leht): üldistus, võrdlus, 2–3 arvu, neutraalne toon, umbes 180 sõna … / 12', 'Kirjutamine 2: mõlemad punktid arendatud, näited, sissejuhatus ja järeldus, 220–260 sõna … / 12', 'Rääkimine 1: ülesehitus, register, vastused küsimustele … / 10', 'Rääkimine 2: sõna võtmine ja andmine, põhjendused ja näited … / 10', 'Kokku: kirjutamine … / 24, rääkimine … / 20; lävend 60% kummaski osas.']),
      B.selfcheck('c1_010_t_self', ['Kirjutamine: sain vähemalt 15 punkti 24-st (60%).', 'Rääkimine: sain vähemalt 12 punkti 20-st (60%).', 'Ma pidasin 2-minutilise kõne plaani järgi ja vastasin küsimustele.', 'Arutelus võtsin ja andsin sõna ega pidanud monoloogi.'], 'Moodul 1 läbitud'),
    ],
